systems/celestial/CelestialStarVfx.js:
import { ASSET_KEYS } from "../../values/assetKeys.js";
import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";
import { CELESTIAL_PRESENTATION as P } from "../../values/celestialPresentation.js";

/** Animates existing Star/Corona artwork with bounded textured wakes and pulses. */
export class CelestialStarVfx {
  constructor({ scene, x, y, assetKey, size, kind, passive = false, delay = 0, coreRadius }) {
    Object.assign(this, { scene, x, y, assetKey, kind, passive });
    this.config = P[kind];
    this.size = size * this.config.sizeScale;
    this.strength = passive ? P.passiveAlpha : 1;
    this.effects = new Set();
    this.trails = new Set();
    this.pulses = new Set();
    this.previous = { x, y };
    this.trailIndex = 0;
    this.lastPulseAt = -Infinity;
    this.startedAt = (scene.time?.now || 0) + delay;
    this.envelope = { value: 0 };
    try {
      this.halo = this._image(x, y, this.size * P.haloScale, 0, P.detailDepthOffset);
      this.halo.setTint?.(...this.config.haloTints);
      if (kind === "hollow") {
        this.core = scene.add.circle(x, y, coreRadius ?? size * P.hollow.passiveCoreRadius, 0, 1)
          .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + P.coreDepthOffset)
          .setAlpha(0);
      }
      this.sprite = this._image(x, y, this.size, 0);
      this.sprite.setTint?.(...this.config.tints);
      if (kind === "hollow") {
        this.sprite.preFX?.addColorMatrix?.()?.hue(this.config.coreHueDeg);
        this.halo.preFX?.addColorMatrix?.()?.hue(this.config.haloHueDeg);
      }
      this._pose(this.startedAt);
      scene.tweens.add({ targets: this.envelope, value: 1, delay,
        duration: P.enterMs, ease: "Sine.out", onUpdate: () => this._pose(scene.time?.now || 0) });
    } catch (error) {
      this.destroy();
      throw error;
    }
  }

  _image(x, y, size, alpha, depthOffset = 0, assetKey = this.assetKey) {
    return this.scene.add.image(x, y, assetKey)
      .setDisplaySize(size, size).setAlpha(alpha)
      .setBlendMode(Phaser.BlendModes.ADD)
      .setDepth(CELESTIAL_ENGINE_CONFIG.fx.worldDepth + depthOffset);
  }

  _pose(nowMs) {
    if (this.destroyed) return;
    const age = Math.max(0, nowMs - this.startedAt);
    const breath = Math.sin(age / P.breathMs * P.fullTurn);
    const envelope = this.envelope.value;
    const size = this.size * (P.enterScale + (1 - P.enterScale) * envelope);
    this.sprite.setDisplaySize(size, size).setAlpha(P.coreAlpha * this.strength * envelope);
    this.halo.setDisplaySize(
      size * P.haloScale * (1 + breath * P.breathScale),
      size * P.haloScale * P.haloAspect * (1 - breath * P.breathScale),
    ).setAlpha(P.haloAlpha * this.strength * envelope);
    this.core?.setAlpha(envelope);
    this.core?.setScale(P.enterScale + (1 - P.enterScale) * envelope
      + breath * P.hollow.coreBreath * envelope);
  }

  setPosition(x, y) {
    this.x = x;
    this.y = y;
    for (const image of [this.sprite, this.halo, this.core]) image?.setPosition(x, y);
  }

  update(nowMs, deltaMs, x = this.x, y = this.y) {
    if (this.destroyed || this.finishing) return;
    this.setPosition(x, y);
    const dt = Math.min(P.maxDeltaMs, Math.max(0, deltaMs || 0)) / P.millisecondsPerSecond;
    this.sprite.angle += this.config.rotationDegPerSecond * dt;
    this.halo.angle += this.config.rotationDegPerSecond * P.haloRotationRatio * dt;
    this._pose(nowMs);
    if (this.kind === "wayward" && nowMs >= this.startedAt) this._trail();
  }

  _trail() {
    const c = this.config;
    const dx = this.x - this.previous.x;
    const dy = this.y - this.previous.y;
    const distance = Math.hypot(dx, dy);
    const spacing = c.trailSpacingPx / this.strength;
    if (distance < spacing) return;
    const count = Math.min(c.trailMaxSamples, Math.floor(distance / spacing));
    for (let index = 0; index < count && this.trails.size < c.trailMaxLive; index += 1) {
      const t = (index + 1) / count;
      const role = c.trailAssetRoles[this.trailIndex % c.trailAssetRoles.length];
      const waveKey = ASSET_KEYS.celestialEngines[role];
      const trailKey = this.scene.textures?.exists?.(waveKey) ? waveKey : this.assetKey;
      const trail = this._image(this.previous.x + dx * t, this.previous.y + dy * t,
        this.size, c.trailAlpha * this.strength, P.detailDepthOffset, trailKey);
      trail.setDisplaySize(this.size * c.trailWidth, this.size * c.trailHeight);
      trail.angle = Math.atan2(dy, dx) * P.degreesPerRadian;
      trail.setTint?.(c.trailTints[this.trailIndex++ % c.trailTints.length]);
      this._track(trail, this.trails);
      this.scene.tweens.add({ targets: trail, alpha: 0,
        scaleX: trail.scaleX * c.trailEndScaleX, scaleY: trail.scaleY * c.trailEndScaleY,
        duration: c.trailLifeMs, ease: "Sine.out", onComplete: () => this._release(trail) });
    }
    this.previous = { x: this.x, y: this.y };
  }

  pulse(radius = this.size * P.pulse.impactRadiusInSizes, index = 0) {
    if (this.destroyed || this.finishing) return false;
    const c = P.pulse;
    const now = this.scene.time?.now || 0;
    const interval = this.passive ? c.passiveIntervalMs : c.minimumIntervalMs;
    if (now - this.lastPulseAt < interval || this.pulses.size >= c.maxLive) return false;
    this.lastPulseAt = now;
    const pulling = this.kind === "hollow";
    const size = Math.min(radius, this.size * c.maxRadiusInSizes) * c.diameterScale;
    const start = pulling ? c.pullStart : c.expandStart;
    const end = pulling ? c.pullEnd : c.expandEnd;
    const pulse = this._image(this.x, this.y, size * start, 0, P.detailDepthOffset);
    pulse.angle = this.sprite.angle + index * c.rotationDeg;
    pulse.setTint?.(...(index % 2 ? this.config.tints : this.config.haloTints));
    this._track(pulse, this.pulses);
    const alpha = this.passive ? c.passiveAlpha : c.alpha;
    this.scene.tweens.add({ targets: pulse, alpha, duration: c.attackMs, ease: "Sine.out",
      onComplete: () => {
        if (!this.effects.has(pulse)) return;
        this.scene.tweens.add({ targets: pulse, alpha: 0,
          scaleX: pulse.scaleX * end / start, scaleY: pulse.scaleY * end / start,
          angle: pulse.angle + (pulling ? -c.rotationDeg : c.rotationDeg),
          duration: c.lifeMs, ease: "Sine.inOut", onComplete: () => this._release(pulse) });
      } });
    return true;
  }

  _track(image, group) {
    this.effects.add(image);
    group.add(image);
  }

  _release(image) {
    this.effects.delete(image);
    this.trails.delete(image);
    this.pulses.delete(image);
    image.destroy?.();
  }

  finish(onComplete) {
    if (this.destroyed || this.finishing) return;
    this.finishing = true;
    this.scene.tweens?.killTweensOf?.(this.envelope);
    this.scene.tweens.add({ targets: this.envelope, value: 0, duration: P.exitMs,
      ease: "Sine.inOut", onUpdate: () => this._pose(this.scene.time?.now || 0),
      onComplete: () => { if (!this.destroyed) onComplete?.(); } });
  }

  getSnapshot() {
    return { liveTrails: this.trails.size, livePulses: this.pulses.size,
      trailSamples: this.trailIndex, passive: this.passive };
  }

  destroy() {
    if (this.destroyed) return;
    this.destroyed = true;
    for (const target of [this.envelope, this.sprite, this.halo, this.core, ...this.effects]) {
      if (!target) continue;
      this.scene.tweens?.killTweensOf?.(target);
      target.destroy?.();
    }
    this.effects.clear();
    this.trails.clear();
    this.pulses.clear();
  }
}

systems/celestial/WaywardStarEngine.js:
import { CelestialStarVfx } from "./CelestialStarVfx.js";
import { CELESTIAL_ENGINE_CONFIG } from "../../values/celestialEngines.js";

export class WaywardStarEngine {
  constructor(options) {
    Object.assign(this, options);
    this.definition = this.definitionOverride
      || CELESTIAL_ENGINE_CONFIG.engines[this.budget.engineId];
    this.x = this.startX;
    this.y = this.startY;
    this.vx = this.direction.x * this.definition.speedTilesPerSecond * this.tileSize;
    this.vy = this.direction.y * this.definition.speedTilesPerSecond * this.tileSize;
    this.supernovaImpacts = 0;
    this.supernovaTargetKeys = new Set();
    this.returning = false;
    this.lastReturnImpactAt = -Infinity;
    this.active = true;
    this.finishing = false;
    try {
      this._createVisual();
    } catch (error) {
      this.active = false;
      this._destroyVisual();
      throw error;
    }
  }

  _createVisual() {
    this.visual = new CelestialStarVfx({ scene: this.scene, x: this.x, y: this.y,
      assetKey: this.assetKey, size: this.definition.displaySizePx, kind: "wayward" });
    this.sprite = this.visual.sprite;
    this.glow = this.visual.halo;
  }

  update(nowMs, deltaMs) {
    if (!this.active) return;
    if (this.returning) {
      this._updateReturn(nowMs, deltaMs);
      return;
    }
    if (this.finishing) return;
    if (this.budget.isExpired(nowMs) || this.budget.isImpactCapReached()) {
      this._finishRoute(nowMs);
      return;
    }

    const dt = Math.min(0.05, Math.max(0, Number(deltaMs) || 0) / 1000);
    const nextX = this.x + this.vx * dt;
    const nextY = this.y + this.vy * dt;
    const xTile = this.toTile(nextX, this.y);
    const yTile = this.toTile(this.x, nextY);
    const diagonalTile = this.toTile(nextX, nextY);
    const blockedX = this.probeTile(xTile.tx, xTile.ty).solid;
    const blockedY = this.probeTile(yTile.tx, yTile.ty).solid;
    const blockedDiagonal = this.probeTile(diagonalTile.tx, diagonalTile.ty).solid;

    if (blockedX || blockedY || blockedDiagonal) {
      const targets = [];
      if (blockedX) targets.push(xTile);
      if (blockedY) targets.push(yTile);
      if (!blockedX && !blockedY && blockedDiagonal) targets.push(diagonalTile);
      this._impactTargets(targets, nowMs);

      if (blockedX || (!blockedY && blockedDiagonal)) this.vx *= -1;
      if (blockedY || (!blockedX && blockedDiagonal)) this.vy *= -1;
      if (!this.budget.tryBounce() || this.budget.bounces >= this.definition.maxBounces) {
        this._finishRoute(nowMs);
        return;
      }
      const momentum = Math.max(1, Number(this.definition.bounceSpeedMultiplier) || 1);
      this.vx *= momentum;
      this.vy *= momentum;
      this._seekFreshTarget();
      this.onBounce?.(this.x, this.y, this.budget.bounces);
    } else {
      this.x = nextX;
      this.y = nextY;
    }

    this.visual.update(nowMs, deltaMs, this.x, this.y);
  }

  _impactTargets(targets, nowMs) {
    const seen = new Set();
    for (const tile of targets) {
      const key = `${tile.tx},${tile.ty}`;
      if (seen.has(key)) continue;
      seen.add(key);
      const hitId = this.budget.tryImpact(tile.tx, tile.ty);
      if (!hitId) continue;
      this.onImpact?.(tile.tx, tile.ty, hitId, nowMs);
    }
    this._spawnImpactRing();
  }

  _finishRoute(nowMs) {
    if (this.finishing || !this.active) return;
    if (this.definition.returnToPlayer === true && this.getAnchor) {
      this.finishing = true;
      this.returning = true;
      this._spawnImpactRing();
      return;
    }
    this._fadeOut("route-complete");
  }

  _fadeOut(reason) {
    if (this.finishing && !this.returning) return;
    this.finishing = true;
    this.returning = false;
    this.visual.finish(() => this._finish(reason));
  }

  _updateReturn(nowMs, deltaMs) {
    const anchor = this.getAnchor?.();
    if (!anchor) {
      this._fadeOut("route-complete");
      return;
    }
    const dx = anchor.x - this.x;
    const dy = anchor.y - this.y;
    const distance = Math.hypot(dx, dy);
    if (distance <= this.tileSize * 0.42) {
      this._fadeOut("returned");
      return;
    }
    const dt = Math.min(0.05, Math.max(0, Number(deltaMs) || 0) / 1000);
    const speed = Math.max(1, Number(this.definition.returnSpeedTilesPerSecond) || 1)
      * this.tileSize;
    const travel = Math.min(distance, speed * dt);
    this.x += dx / distance * travel;
    this.y += dy / distance * travel;
    this.visual.update(nowMs, deltaMs, this.x, this.y);
    if (this.definition.returnCanImpact === true) this._impactReturnTile(nowMs);
  }

  _impactReturnTile(nowMs) {
    const cooldown = Math.max(0, Number(this.definition.returnImpactCooldownMs) || 0);
    if (nowMs - this.lastReturnImpactAt < cooldown) return;
    const tile = this.toTile(this.x, this.y);
    if (!this.probeTile(tile.tx, tile.ty).diggable) return;
    const hitId = this.budget.tryImpact(tile.tx, tile.ty);
    if (!hitId) return;
    this.lastReturnImpactAt = nowMs;
    this.onImpact?.(tile.tx, tile.ty, hitId, nowMs);
    this._spawnImpactRing();
  }

  _seekFreshTarget() {
    if (this.definition.seekFreshTargets !== true) return;
    const radius = Math.max(1, Math.floor(Number(this.definition.seekRadiusTiles) || 1));
    const center = this.toTile(this.x, this.y);
    let best = null;
    for (let oy = -radius; oy <= radius; oy += 1) {
      for (let ox = -radius; ox <= radius; ox += 1) {
        const distance = Math.hypot(ox, oy);
        if (distance <= 0 || distance > radius) continue;
        const tx = center.tx + ox;
        const ty = center.ty + oy;
        if (this.budget._targetKeys.has(`${tx},${ty}`)) continue;
        if (!this.probeTile(tx, ty).diggable) continue;
        if (!best || distance < best.distance) best = { tx, ty, distance };
      }
    }
    if (!best) return;
    const targetX = best.tx * this.tileSize + this.tileSize / 2;
    const targetY = best.ty * this.tileSize + this.tileSize / 2;
    const dx = targetX - this.x;
    const dy = targetY - this.y;
    const length = Math.hypot(dx, dy) || 1;
    const speed = Math.hypot(this.vx, this.vy);
    this.vx = dx / length * speed;
    this.vy = dy / length * speed;
  }

  _spawnImpactRing() {
    this.visual.pulse();
  }

  _finish(reason) {
    if (!this.active) return;
    this.active = false;
    this.onComplete?.(reason, {
      ...this.getSnapshot(this.scene.time?.now || 0),
    });
    this._destroyVisual();
  }

  getSnapshot(nowMs) {
    const route = this.budget.getSnapshot(nowMs);
    const maxSupernovaImpacts = Math.max(
      0,
      Math.floor(Number(this.definition.supernovaMaxImpacts) || 0),
    );
    const uniqueTargets = new Set([
      ...this.budget._targetKeys,
      ...this.supernovaTargetKeys,
    ]).size;
    return {
      ...route,
      active: this.active,
      finishing: this.finishing,
      returning: this.returning,
      remainingMs: Math.max(0, route.lifetimeMs - route.ageMs),
      routeImpacts: route.impacts,
      maxRouteImpacts: route.maxImpacts,
      supernovaImpacts: this.supernovaImpacts,
      maxSupernovaImpacts,
      impacts: route.impacts + this.supernovaImpacts,
      maxImpacts: route.maxImpacts + maxSupernovaImpacts,
      uniqueTargets,
    };
  }

  _destroyVisual() {
    this.visual?.destroy();
  }

  destroy() {
    this.active = false;
    this._destroyVisual();
  }
}

